#include "sheetnest/dxf.hpp"
#include <sstream>
#include <cmath>
namespace sheetnest{struct P{std::string c,v;};static double n(const std::string&s){try{return std::stod(s);}catch(...){return 0;}}static std::vector<P>read(const std::string&s){std::istringstream i(s);std::string c,v;std::vector<P>p;while(std::getline(i,c)&&std::getline(i,v))p.push_back({c,v});return p;}static Polygon circle(double x,double y,double r){Polygon p;for(int i=0;i<64;i++){double a=6.283185307179586*i/64.;p.push_back({x+r*std::cos(a),y+r*std::sin(a)});}return p;}DxfDocument importDxf(const std::string&s,double){DxfDocument o;auto p=read(s);for(size_t i=0;i<p.size();++i)if(p[i].c=="0"){if(p[i].v=="CIRCLE"){double x=0,y=0,r=0;for(size_t j=i+1;j<p.size()&&p[j].c!="0";++j){if(p[j].c=="10")x=n(p[j].v);else if(p[j].c=="20")y=n(p[j].v);else if(p[j].c=="40")r=n(p[j].v);}if(r>0)o.contours.push_back({circle(x,y,r),{},"CIRCLE"});}else if(p[i].v=="LWPOLYLINE"){Polygon g;bool closed=false;for(size_t j=i+1;j<p.size()&&p[j].c!="0";++j){if(p[j].c=="10"&&j+1<p.size()&&p[j+1].c=="20")g.push_back({n(p[j].v),n(p[j+1].v)});else if(p[j].c=="70")closed=((int)n(p[j].v)&1)!=0;}if(closed&&g.size()>=3)o.contours.push_back({g,{},"LWPOLYLINE"});}}return o;}}
